import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, isAbsolute, join } from "node:path";
import type { DiscoveredTask, TaskRegistry } from "@/src/discovery";
import { ConfigError, ToolError } from "@/src/errors";

export const GENERATED_MARKER = "<!-- Generated by tasknest; do not edit by hand. -->";

export const DEFAULT_SKILL_TEMPLATE = [
  "<!-- Generated by tasknest; do not edit by hand. -->",
  "# Project Tools Skill",
  "",
  "Run repository tasks with `{{ command }}`.",
  "",
  "## Tasks",
  "{% for task in tasks %}",
  "### `{{ task.cli_command }}` (`{{ task.name }}`)",
  "{% if task.description %}{{ task.description }}",
  "{% endif %}{% if task.marks %}- Marks: {{ task.marks }}",
  "{% endif %}{% if task.requires %}- Requires: {{ task.requires }}",
  "{% endif %}{% if task.depends %}- Depends: {{ task.depends }}",
  "{% endif %}{% if task.persistent %}- Persistent: true",
  "{% endif %}{% if task.options %}- Options: {{ task.options }}",
  "{% endif %}{% endfor %}",
].join("\n");

interface JinjaModule {
  Template: new (source: string) => { render(items?: Record<string, unknown>): string };
}

async function loadJinjaModule(): Promise<JinjaModule> {
  try {
    return (await import("@huggingface/jinja")) as unknown as JinjaModule;
  } catch (err) {
    throw new ConfigError(
      `'@huggingface/jinja' is required for skill generation: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

function formatTaskEntry(task: DiscoveredTask, command: string): Record<string, string> {
  const cliPath = task.cliPath.join(" ");
  const deps = task.definition.depends
    .map((dep) => (typeof dep === "string" ? dep : dep.name))
    .join(", ");
  const opts = task.definition.options.map((opt) => `${opt.flagName} <${opt.baseType}>`).join(", ");
  return {
    name: task.canonicalName,
    cli_path: cliPath,
    cli_command: `${command} run ${cliPath}`,
    description: task.description.trim(),
    marks: task.definition.marks.join(", "),
    requires: task.definition.requires.join(", "),
    depends: deps,
    persistent: task.definition.persistent ? "true" : "",
    options: opts,
  };
}

function resolveTemplateSource(registry: TaskRegistry, templatePath?: string): string {
  const configured =
    templatePath !== undefined
      ? templatePath
      : registry.config.skill.template !== undefined
        ? join(registry.config.repoRoot, registry.config.skill.template)
        : undefined;
  if (configured === undefined) {
    return DEFAULT_SKILL_TEMPLATE;
  }
  if (!existsSync(configured)) {
    throw new ConfigError(`Skill template not found: ${configured}`);
  }
  return readFileSync(configured, "utf-8");
}

export function resolveSkillOutput(registry: TaskRegistry, outputPath?: string): string {
  if (outputPath !== undefined) {
    return isAbsolute(outputPath) ? outputPath : join(registry.config.repoRoot, outputPath);
  }
  return join(registry.config.repoRoot, registry.config.skill.output);
}

export async function renderSkill(
  registry: TaskRegistry,
  options: { readonly templatePath?: string } = {},
): Promise<string> {
  const jinja = await loadJinjaModule();
  const source = resolveTemplateSource(registry, options.templatePath);
  const command = registry.config.skill.command;
  const tasks = Object.values(registry.tasks)
    .sort((a, b) => a.canonicalName.localeCompare(b.canonicalName))
    .map((task) => formatTaskEntry(task, command));
  const rendered = new jinja.Template(source).render({ command, tasks });
  return rendered.endsWith("\n") ? rendered : `${rendered}\n`;
}

export async function checkSkill(
  registry: TaskRegistry,
  options: { readonly outputPath?: string; readonly templatePath?: string } = {},
): Promise<boolean> {
  const target = resolveSkillOutput(registry, options.outputPath);
  if (!existsSync(target)) {
    return false;
  }
  const expected = await renderSkill(
    registry,
    options.templatePath !== undefined ? { templatePath: options.templatePath } : {},
  );
  return readFileSync(target, "utf-8") === expected;
}

export async function writeSkill(
  registry: TaskRegistry,
  options: {
    readonly outputPath?: string;
    readonly templatePath?: string;
    readonly force?: boolean;
  } = {},
): Promise<string> {
  const target = resolveSkillOutput(registry, options.outputPath);
  if (existsSync(target) && !(options.force ?? false)) {
    const existing = readFileSync(target, "utf-8");
    if (!existing.includes(GENERATED_MARKER)) {
      throw new ToolError(
        `Refusing to overwrite manual skill file ${target} without force=true (--force).`,
      );
    }
  }
  const rendered = await renderSkill(
    registry,
    options.templatePath !== undefined ? { templatePath: options.templatePath } : {},
  );
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, rendered, "utf-8");
  return target;
}
